mapper.select:
select t.person_name,t.person_name personName,t.res_param,t.res_param resParam,t.machine_id,t.machine_id
machineId,t.log_id,t.log_id logId,t.person_id,t.person_id personId,t.req_param,t.req_param
reqParam,t.state,t.community_id,t.community_id communityId,t.log_action,t.log_action logAction,
t.create_time createTime, lm.machine_name machineName, lm.machine_code machineCode, sm.name communityName, td.name stateName,
td1.name logActionName
from lift_machine_log t
left join lift_machine lm on t.machine_id = lm.machine_id
left join s_community sm on t.community_id = sm.community_id
left join t_dict td on t.state = td.status_cd and td.table_name = 'lift_machine_log' and td.table_columns = 'state'
left join t_dict td1 on t.log_action = td1.status_cd and td1.table_name = 'lift_machine_log' and td1.table_columns = 'log_action'
where 1 =1

    and t.person_name= #{personName}


    and t.res_param= #{resParam}


    and t.machine_id= #{machineId}


    and t.log_id= #{logId}


    and t.person_id= #{personId}


    and t.req_param= #{reqParam}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.log_action= #{logAction}

order by t.create_time desc

    limit #{page}, #{row}

